const sections = {
  dashboard: ["Dashboard", "⌂", "学習ダッシュボードです。"],
  vocabulary: ["語彙", "文", "N1レベルの重要単語をここで学習できます。"],
  grammar: ["文法", "文", "N1文法を例文とクイズで学習できます。"],
  kanji: ["漢字", "漢", "N1で必要な漢字を効率よく覚えられます。"],
  reading: ["読解", "読", "N1読解問題を時間を測りながら練習できます。"],
  listening: ["聴解", "聴", "N1聴解問題を音声付きで練習できます。"],
  mock: ["模擬試験", "✓", "本番形式のN1模擬試験に挑戦できます。"]
};

function showToast(message) {
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(window.toastTimer);
  window.toastTimer = setTimeout(() => toast.classList.remove("show"), 2200);
}

function openSection(key) {
  const [title, icon, text] = sections[key] || sections.dashboard;
  pageTitle.textContent = title;

  navItems.forEach(item => {
    item.classList.toggle("active", item.dataset.section === key);
  });

  dashboardSection.hidden = key !== "dashboard";
  vocabularySection.hidden = key !== "vocabulary";
  document.getElementById("kanjiSection").hidden = key !== "kanji";
  placeholderSection.hidden = key === "dashboard" || key === "vocabulary" || key === "kanji";

  if (key !== "dashboard" && key !== "vocabulary") {
    placeholderTitle.textContent = title;
    placeholderIcon.textContent = icon;
    placeholderText.textContent = text;
  }

  if (key === "vocabulary") initVocabulary();
  if (key === "kanji") initKanji();

  sidebar.classList.remove("open");
  window.scrollTo({top: 0, behavior: "smooth"});
}

navItems.forEach(item => {
  item.addEventListener("click", event => {
    event.preventDefault();
    openSection(item.dataset.section);
  });
});

document.querySelectorAll("[data-start]").forEach(button => {
  button.addEventListener("click", () => {
    const target = button.dataset.start === "語彙" ? "vocabulary" :
      button.dataset.start === "文法" ? "grammar" : "kanji";
    openSection(target);
  });
});

document.getElementById("backDashboard").addEventListener("click", () => openSection("dashboard"));

document.getElementById("menuBtn").addEventListener("click", () => {
  sidebar.classList.toggle("open");
});

document.getElementById("tipBtn").addEventListener("click", () => {
  const tips = [
    "知らない単語は例文と一緒に覚えると定着しやすいです。",
    "N1読解は先に設問を確認してから本文を読むのもおすすめです。",
    "毎日20問でも、継続すれば大きな力になります。"
  ];
  showToast(tips[Math.floor(Math.random() * tips.length)]);
});

document.getElementById("resetBtn").addEventListener("click", () => {
  document.getElementById("progressText").textContent = "0%";
  document.getElementById("miniProgress").style.width = "0%";
  document.getElementById("todayCount").textContent = "0 / 50";
  showToast("今日の進捗をリセットしました。");
});

