const LESSON_SIZE = 25;
const LESSONS = [];
for (let i = 0; i < PDF_VOCABULARY.length; i += LESSON_SIZE) {
  LESSONS.push(PDF_VOCABULARY.slice(i, i + LESSON_SIZE));
}

const QUIZ_KEY = "n1_pdf_vocab_lessons_v2";
let quiz = { lessonId: 0, order: [], index: 0, score: 0, answered: false };

function normalizeAnswer(value) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/\s+/g, "")
    .trim()
    .toLowerCase();
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function loadLessonProgress() {
  try { return JSON.parse(localStorage.getItem(QUIZ_KEY) || "{}"); }
  catch { return {}; }
}

function saveLessonProgress() {
  const all = loadLessonProgress();
  all[quiz.lessonId] = {
    order: quiz.order,
    index: quiz.index,
    score: quiz.score,
    answered: quiz.answered,
    done: quiz.done || false
  };
  localStorage.setItem(QUIZ_KEY, JSON.stringify(all));
}

function renderLessonProgress() {
  const all = loadLessonProgress();
  LESSONS.forEach((words, i) => {
    const saved = all[i + 1];
    const bar = document.getElementById(`lessonBar-$47`);
    const text = document.getElementById(`lessonProgress-$47`);
    if (!bar || !text) return;
    const completed = saved?.done ? words.length : Math.min(saved ? saved.index + (saved.answered ? 1 : 0) : 0, words.length);
    const percent = words.length ? Math.round((completed / words.length) * 100) : 0;
    bar.style.width = `${percent}%`;
    text.textContent = percent === 100 ? "Hoàn thành ✓" : percent ? `Đã học ${completed}/${words.length}` : "Chưa học";
  });
}

function addVocabularyPdfButtons() {
  const cards = document.querySelectorAll("#lessonListView .vocab-lesson-card[data-lesson]");
  cards.forEach(card => {
    const lessonId = Number(card.dataset.lesson);
    if (!lessonId || card.querySelector(".pdf-lesson-btn")) return;
    const words = PDF_VOCABULARY.slice((lessonId - 1) * 25, lessonId * 25);
    if (!words.length) return;
    const pages = [...new Set(words.map(item => Number(item.source_page)).filter(Boolean))].sort((a, b) => a - b);
    if (!pages.length) return;

    const startBtn = card.querySelector(".lesson-open-btn");
    if (!startBtn) return;
    const actions = document.createElement("div");
    actions.className = "lesson-actions";
    startBtn.parentNode.insertBefore(actions, startBtn);
    actions.appendChild(startBtn);

    const pdfBtn = document.createElement("a");
    pdfBtn.className = "pdf-lesson-btn";
    pdfBtn.href = `./vocab-pdf/Bai-${String(lessonId).padStart(2, "0")}.pdf`;
    pdfBtn.target = "_blank";
    pdfBtn.rel = "noopener";
    pdfBtn.innerHTML = "📄 PDF";
    pdfBtn.title = `Mở PDF Bài ${String(lessonId).padStart(2, "0")} · trang ${pages[0]}${pages.length > 1 ? "–" + pages[pages.length - 1] : ""}`;
    pdfBtn.addEventListener("click", event => event.stopPropagation());
    actions.appendChild(pdfBtn);
  });
}

function initVocabulary() {
  addVocabularyPdfButtons();
  document.getElementById("lessonListView").hidden = false;
  document.getElementById("lessonQuizView").hidden = true;
  renderLessonProgress();
}

function shuffle(array) {
  const result = [...array];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

function startLesson(lessonId) {
  const words = LESSONS[lessonId - 1];
  if (!words) return;
  const all = loadLessonProgress();
  const saved = all[lessonId];
  if (saved && Array.isArray(saved.order) && saved.order.length === words.length && !saved.done) {
    quiz = { ...saved, lessonId };
  } else {
    quiz = { lessonId, order: shuffle(words.map((_, i) => i)), index: 0, score: 0, answered: false, done: false };
  }
  document.getElementById("lessonListView").hidden = true;
  document.getElementById("lessonQuizView").hidden = false;
  document.getElementById("lessonQuizEyebrow").textContent = `BÀI ${String(lessonId).padStart(2,"0")} · PDF N1 VOCABULARY`;
  saveLessonProgress();
  renderQuestion();
  window.scrollTo({top: 0, behavior: "smooth"});
}

function currentWord() {
  const words = LESSONS[quiz.lessonId - 1] || [];
  return words[quiz.order[quiz.index]];
}

function renderQuestion() {
  const item = currentWord();
  if (!item) return;
  document.getElementById("quizProgressText").textContent = `${quiz.index + 1} / ${quiz.order.length}`;
  document.getElementById("quizScoreText").textContent = `正解 ${quiz.score}`;
  document.getElementById("quizProgressBar").style.width = `${((quiz.index + 1) / quiz.order.length) * 100}%`;
  document.getElementById("questionMeaning").textContent = item.meaning;
  const input = document.getElementById("answerInput");
  input.value = "";
  input.disabled = false;
  document.getElementById("answerResult").className = "answer-result";
  document.getElementById("answerResult").innerHTML = "";
  document.getElementById("showAnswerBtn").textContent = "Xem đáp án";
  quiz.answered = false;
  input.focus();
}

const AUTO_NEXT_CORRECT_DELAY = 1200;
const AUTO_NEXT_WRONG_DELAY = 2200;
let autoNextTimer = null;

function scheduleAutoNext(delay) {
  clearTimeout(autoNextTimer);
  autoNextTimer = setTimeout(() => {
    autoNextTimer = null;
    advanceQuestion();
  }, delay);
}

function advanceQuestion() {
  clearTimeout(autoNextTimer);
  autoNextTimer = null;
  if (!quiz.order.length) return;
  if (quiz.index >= quiz.order.length - 1) {
    quiz.done = true;
    saveLessonProgress();
    renderLessonProgress();
    showToast(`Hoàn thành Bài ${String(quiz.lessonId).padStart(2,"0")}! Kết quả: ${quiz.score}/${quiz.order.length}`);
    initVocabulary();
    return;
  }
  quiz.index++;
  quiz.answered = false;
  saveLessonProgress();
  renderQuestion();
}

function checkAnswer() {
  if (quiz.answered) return;
  const input = document.getElementById("answerInput").value;
  const item = currentWord();
  if (!item || !input.trim()) { showToast("Hãy nhập câu trả lời tiếng Nhật."); return; }
  const correct = normalizeAnswer(input) === normalizeAnswer(item.word);
  const result = document.getElementById("answerResult");
  quiz.answered = true;
  if (correct) {
    quiz.score++;
    result.className = "answer-result correct";
    result.innerHTML = `🎉 <strong>Chính xác!</strong>　${escapeHtml(item.word)}`;
  } else {
    result.className = "answer-result wrong";
    result.innerHTML = `✕ <strong>Chưa đúng</strong><br>Đáp án: <b>${escapeHtml(item.word)}</b>${item.reading ? `（${escapeHtml(item.reading)}）` : ""}`;
  }
  document.getElementById("answerInput").disabled = true;
  document.getElementById("quizScoreText").textContent = `正解 ${quiz.score}`;
  saveLessonProgress();
  renderLessonProgress();
  scheduleAutoNext(correct ? AUTO_NEXT_CORRECT_DELAY : AUTO_NEXT_WRONG_DELAY);
}

document.getElementById("answerForm").addEventListener("submit", e => { e.preventDefault(); checkAnswer(); });

document.getElementById("showAnswerBtn").addEventListener("click", () => {
  const item = currentWord();
  if (!item) return;
  const result = document.getElementById("answerResult");
  result.className = "answer-result reveal";
  result.innerHTML = `💡 Đáp án: <b>${escapeHtml(item.word)}</b>${item.reading ? `（${escapeHtml(item.reading)}）` : ""}`;
  quiz.answered = true;
  document.getElementById("answerInput").disabled = true;
  saveLessonProgress();
  scheduleAutoNext(AUTO_NEXT_WRONG_DELAY);
});

document.getElementById("nextQuestionBtn").addEventListener("click", advanceQuestion);

document.getElementById("backLessonsBtn").addEventListener("click", () => {
  clearTimeout(autoNextTimer);
  autoNextTimer = null;
  initVocabulary();
});

document.querySelectorAll(".vocab-lesson-card").forEach(card => {
  card.addEventListener("click", () => {
    const id = Number(card.dataset.lesson);
    if (id) startLesson(id);
  });
});

document.querySelector(".icon-btn").addEventListener("click", () => showToast("新しい通知はありません。"));

